INSERT INTO _of_res VALUES
  ('OF-M-ICB', 'Impermeabilizante cementicio bicomponente', 'kg', 'MATERIAL', 3200, 'Estimado ObraFlow octubre 2026 (kit 25 kg); verificar con tu proveedor');
INSERT INTO public.resources (catalog_id, organization_id, code, name, unit, base_cost, type, pricing_notes, is_active)
INSERT INTO _of_tasks VALUES
  ('OF-FUN-104', 'Zapata corrida de hormigón armado', 'm³', '04 FUNDACIONES', 'Cimiento corrido de hormigón armado H-21 bajo muros portantes. A diferencia de OF-FUN-002 (zapata de hormigón ciclópeo, sin armar) lleva armadura; a diferencia de OF-FUN-004 (viga de fundación) trabaja como base ancha y baja. El hormigón de limpieza va aparte (OF-FUN-001).', 'Dimensiones y armadura según cálculo; cuantía orientativa 40–70 kg/m³', 1.75),
  ('OF-YES-104', 'Jaharro y enlucido de yeso sobre mampostería', 'm²', '15 YESERIA', 'Terminación interior de paredes con jaharro de yeso y enlucido a la llana, lista para pintar. Reemplaza al revoque grueso + fino a la cal en locales secos. Para cielorrasos usar OF-CIE-003.', 'Espesor ≈ 1,2 cm; solo interiores secos', 17.5),
  ('OF-IMP-003', 'Impermeabilización cementicia de piso de baño', 'm²', '93 AISLACIONES Y MEMBRANAS', 'Impermeabilizante cementicio bicomponente en dos manos sobre la carpeta, con subida en muros y banda de refuerzo en encuentros. Distinto de OF-IMP-001 (balcones, por unidad) y de OF-CAR-103 (carpeta hidrófuga): se pueden usar juntos.', 'Subida ≥ 20 cm (en ducha ≥ 1,80 m); medir la superficie desarrollada', 27.5),
  ('OF-SAN-128', 'Boca de agua fría y caliente (termofusión)', 'u', '23 INSTALACIÓN SANITARIA', 'Alimentación completa de un artefacto con agua fría y caliente en termofusión, desde el ramal hasta la conexión de la grifería. Alternativa por boca a OF-SAN-001 y OF-SAN-002 (por ml): usar una forma de cómputo u otra, no ambas.', 'PPR 20 mm embutido; prueba de presión antes de tapar', 3.5);
