INSERT INTO _of_fichas VALUES
  ('DEM-MAM', $sheet${"version": 1, "ficha": "DEM-MAM", "gremio": "Demoliciones", "titulo": "Demolición de mampostería con retiro de escombros", "esquemaSvg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 590 300\" role=\"img\" aria-label=\"Demolición de mampostería\"><defs><pattern id=\"p-mamp\" width=\"24\" height=\"14\" patternUnits=\"userSpaceOnUse\"><rect width=\"24\" height=\"14\" fill=\"#d8a58a\"/><path d=\"M0 0H24M0 7H24M12 0V7M0 7V14M24 7V14\" stroke=\"#f1e6dc\" stroke-width=\"1.4\"/></pattern></defs><style>.lbl{font:11px Arial,Helvetica,sans-serif;fill:#333}.dim{font:10.5px Arial,Helvetica,sans-serif;fill:#555}</style><defs><marker id=\"arr\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0 0L6 3L0 6z\" fill=\"#555\"/></marker></defs><rect x=\"60\" y=\"60\" width=\"170\" height=\"200\" fill=\"url(#p-mamp)\" stroke=\"#9b6e57\" stroke-width=\"1\" /><rect x=\"230\" y=\"150\" width=\"60\" height=\"110\" fill=\"url(#p-mamp)\" stroke=\"#9b6e57\" stroke-width=\"1\" /><path d=\"M230 60 L230 150 L290 150 L290 260\" fill=\"none\" stroke=\"#5a4033\" stroke-width=\"1.5\" stroke-dasharray=\"6 4\"/><rect x=\"40\" y=\"260\" width=\"480\" height=\"6\" fill=\"#999\" stroke=\"#777\" stroke-width=\"1\" /><path d=\"M320 248 l12 -3 l4 9 l-13 3z\" fill=\"#c98f74\" stroke=\"#8d5d48\" stroke-width=\".8\"/><path d=\"M340 252 l12 -3 l4 9 l-13 3z\" fill=\"#c98f74\" stroke=\"#8d5d48\" stroke-width=\".8\"/><path d=\"M360 246 l12 -3 l4 9 l-13 3z\" fill=\"#c98f74\" stroke=\"#8d5d48\" stroke-width=\".8\"/><path d=\"M335 240 l12 -3 l4 9 l-13 3z\" fill=\"#c98f74\" stroke=\"#8d5d48\" stroke-width=\".8\"/><path d=\"M352 236 l12 -3 l4 9 l-13 3z\" fill=\"#c98f74\" stroke=\"#8d5d48\" stroke-width=\".8\"/><path d=\"M375 252 l12 -3 l4 9 l-13 3z\" fill=\"#c98f74\" stroke=\"#8d5d48\" stroke-width=\".8\"/><path d=\"M390 250 l12 -3 l4 9 l-13 3z\" fill=\"#c98f74\" stroke=\"#8d5d48\" stroke-width=\".8\"/><path d=\"M368 240 l12 -3 l4 9 l-13 3z\" fill=\"#c98f74\" stroke=\"#8d5d48\" stroke-width=\".8\"/><path d=\"M420 200 L520 200 L508 256 L432 256 Z\" fill=\"#e8b84a\" stroke=\"#9c7a24\"/><path d=\"M380 225 Q400 205 420 212\" fill=\"none\" stroke=\"#555\" stroke-width=\"1.2\" marker-end=\"url(#arr)\"/><path d=\"M150 120 L150 40\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"150\" y=\"34\" text-anchor=\"middle\">Mampostería existente</text><path d=\"M262 150 L300 70\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"300\" y=\"64\" text-anchor=\"middle\">Línea de corte</text><path d=\"M355 240 L330 285\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"330\" y=\"296\" text-anchor=\"middle\">Escombro (esponjamiento ≈ 30 %)</text><text class=\"lbl\" x=\"470\" y=\"190\" text-anchor=\"middle\">Volquete / contenedor</text></svg>", "pie": "Elevación. Esquema ilustrativo, sin escala.", "descripcion": "Demolición manual de muros de ladrillo, con carga del escombro en volquete y retiro. Antes de demoler hay que verificar que el muro no sea portante y cortar las instalaciones que pasan por él.", "datosTecnicos": [{"label": "Esponjamiento del escombro", "value": "≈ 30 %"}, {"label": "Volquete habitual", "value": "5–6 m³"}, {"label": "Peso mampostería común", "value": "≈ 1.600 kg/m³"}], "notas": ["Apuntalar dinteles y losas antes de retirar apoyos.", "Regar para evitar polvo; proteger pisos y aberturas existentes."], "fuente": "Valores de referencia de práctica habitual en AMBA. Ajustar al proyecto, al proveedor y al estudio de suelos o cálculo cuando corresponda."}$sheet$::jsonb),
  ('MS-EXC', $sheet${"version": 1, "ficha": "MS-EXC", "gremio": "Movimiento de suelos", "titulo": "Excavación manual de zanjas para cimientos", "esquemaSvg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 590 300\" role=\"img\" aria-label=\"Excavación de zanja para cimientos\"><defs><pattern id=\"p-tierra\" width=\"16\" height=\"16\" patternUnits=\"userSpaceOnUse\"><rect width=\"16\" height=\"16\" fill=\"#e2d5bf\"/><path d=\"M2 4l4 4M10 2l3 3M6 12l4 3\" stroke=\"#b9a684\" stroke-width=\"1\"/></pattern></defs><style>.lbl{font:11px Arial,Helvetica,sans-serif;fill:#333}.dim{font:10.5px Arial,Helvetica,sans-serif;fill:#555}</style><rect x=\"30\" y=\"90\" width=\"500\" height=\"190\" fill=\"url(#p-tierra)\" stroke=\"none\" stroke-width=\"0\" /><rect x=\"230\" y=\"90\" width=\"100\" height=\"150\" fill=\"#fafafa\" stroke=\"#8a7a5c\" stroke-width=\"1\" /><path d=\"M30 90 H230 M330 90 H530\" stroke=\"#6b5a3c\" stroke-width=\"2\"/><path d=\"M60 90 Q120 40 180 90 Z\" fill=\"url(#p-tierra)\" stroke=\"#8a7a5c\"/><g stroke=\"#666\" stroke-width=\"1\"><line x1=\"230\" y1=\"262\" x2=\"330\" y2=\"262\"/><line x1=\"230\" y1=\"256\" x2=\"230\" y2=\"268\"/><line x1=\"330\" y1=\"256\" x2=\"330\" y2=\"268\"/></g><text class=\"dim\" x=\"280.0\" y=\"276\" text-anchor=\"middle\">ancho 0,40–0,60 m</text><g stroke=\"#666\" stroke-width=\"1\"><line x1=\"350\" y1=\"90\" x2=\"350\" y2=\"240\"/><line x1=\"344\" y1=\"90\" x2=\"356\" y2=\"90\"/><line x1=\"344\" y1=\"240\" x2=\"356\" y2=\"240\"/></g><text class=\"dim\" x=\"358\" y=\"169.0\" text-anchor=\"start\">prof. según estudio de suelos</text><path d=\"M120 66 L120 30\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"120\" y=\"24\" text-anchor=\"middle\">Suelo extraído: +25 % por esponjamiento</text><path d=\"M440 160 L470 60\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"470\" y=\"54\" text-anchor=\"middle\">Terreno natural</text><path d=\"M280 235 L280 205\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"280\" y=\"200\" text-anchor=\"middle\">Fondo limpio y nivelado</text></svg>", "pie": "Corte. Esquema ilustrativo, sin escala.", "descripcion": "Excavación a mano de zanjas para cimientos corridos o vigas de fundación, con perfilado de paredes y fondo. La profundidad y el ancho salen del estudio de suelos y del cálculo estructural.", "datosTecnicos": [{"label": "Esponjamiento del suelo", "value": "≈ 25 %"}, {"label": "Ancho habitual", "value": "0,40–0,60 m"}, {"label": "Fondo", "value": "limpio, nivelado, sin agua"}], "notas": ["Con napas o paredes inestables, entibar o bombear.", "No dejar la zanja abierta muchos días antes de hormigonar."], "fuente": "Valores de referencia de práctica habitual en AMBA. Ajustar al proyecto, al proveedor y al estudio de suelos o cálculo cuando corresponda."}$sheet$::jsonb),
  ('HA-ZAP', $sheet${"version": 1, "ficha": "HA-ZAP", "gremio": "Hormigón armado", "titulo": "Zapata corrida de hormigón armado H-21", "esquemaSvg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 590 300\" role=\"img\" aria-label=\"Zapata corrida de hormigón armado\"><defs><pattern id=\"p-tierra\" width=\"16\" height=\"16\" patternUnits=\"userSpaceOnUse\"><rect width=\"16\" height=\"16\" fill=\"#e2d5bf\"/><path d=\"M2 4l4 4M10 2l3 3M6 12l4 3\" stroke=\"#b9a684\" stroke-width=\"1\"/></pattern><pattern id=\"p-horm\" width=\"12\" height=\"12\" patternUnits=\"userSpaceOnUse\"><rect width=\"12\" height=\"12\" fill=\"#c4c8cc\"/><circle cx=\"3\" cy=\"3\" r=\"1.1\" fill=\"#8f969c\"/><circle cx=\"9\" cy=\"8\" r=\".9\" fill=\"#8f969c\"/><path d=\"M7 2l2 1-1 2z\" fill=\"#a3a9ae\"/></pattern><pattern id=\"p-mamp\" width=\"24\" height=\"14\" patternUnits=\"userSpaceOnUse\"><rect width=\"24\" height=\"14\" fill=\"#d8a58a\"/><path d=\"M0 0H24M0 7H24M12 0V7M0 7V14M24 7V14\" stroke=\"#f1e6dc\" stroke-width=\"1.4\"/></pattern></defs><style>.lbl{font:11px Arial,Helvetica,sans-serif;fill:#333}.dim{font:10.5px Arial,Helvetica,sans-serif;fill:#555}</style><rect x=\"30\" y=\"70\" width=\"500\" height=\"210\" fill=\"url(#p-tierra)\" stroke=\"none\" stroke-width=\"0\" /><rect x=\"190\" y=\"216\" width=\"180\" height=\"10\" fill=\"url(#p-horm)\" stroke=\"#8f969c\" stroke-width=\"1\" /><rect x=\"190\" y=\"156\" width=\"180\" height=\"60\" fill=\"url(#p-horm)\" stroke=\"#6f767c\" stroke-width=\"1.4\" /><rect x=\"240\" y=\"70\" width=\"80\" height=\"86\" fill=\"url(#p-mamp)\" stroke=\"#9b6e57\" stroke-width=\"1\" /><rect x=\"200\" y=\"164\" width=\"160\" height=\"44\" fill=\"none\" stroke=\"#7b8794\" stroke-width=\"1.6\"/><circle cx=\"210\" cy=\"200\" r=\"4\" fill=\"#3d454d\"/><circle cx=\"250\" cy=\"200\" r=\"4\" fill=\"#3d454d\"/><circle cx=\"310\" cy=\"200\" r=\"4\" fill=\"#3d454d\"/><circle cx=\"350\" cy=\"200\" r=\"4\" fill=\"#3d454d\"/><circle cx=\"210\" cy=\"172\" r=\"3.2\" fill=\"#3d454d\"/><circle cx=\"350\" cy=\"172\" r=\"3.2\" fill=\"#3d454d\"/><g stroke=\"#666\" stroke-width=\"1\"><line x1=\"190\" y1=\"250\" x2=\"370\" y2=\"250\"/><line x1=\"190\" y1=\"244\" x2=\"190\" y2=\"256\"/><line x1=\"370\" y1=\"244\" x2=\"370\" y2=\"256\"/></g><text class=\"dim\" x=\"280.0\" y=\"264\" text-anchor=\"middle\">ancho según cálculo (≥ 0,40 m)</text><g stroke=\"#666\" stroke-width=\"1\"><line x1=\"390\" y1=\"156\" x2=\"390\" y2=\"216\"/><line x1=\"384\" y1=\"156\" x2=\"396\" y2=\"156\"/><line x1=\"384\" y1=\"216\" x2=\"396\" y2=\"216\"/></g><text class=\"dim\" x=\"398\" y=\"190.0\" text-anchor=\"start\">h ≥ 0,30 m</text><path d=\"M355 200 L450 120\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"452\" y=\"116\" text-anchor=\"start\">Armadura ADN 420</text><path d=\"M320 168 L452 150\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"452\" y=\"146\" text-anchor=\"start\">Estribos</text><path d=\"M220 221 L120 262\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"40\" y=\"274\" text-anchor=\"start\">Hormigón de limpieza 5 cm</text><path d=\"M200 180 L110 190\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"108\" y=\"194\" text-anchor=\"end\">Hormigón H-21</text><path d=\"M280 90 L280 40\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"280\" y=\"34\" text-anchor=\"middle\">Muro de arranque</text></svg>", "pie": "Corte. Esquema ilustrativo, sin escala.", "descripcion": "Cimiento corrido de hormigón armado bajo muros portantes, con hormigón de limpieza en el fondo. Las dimensiones y la armadura las define el cálculo estructural; los valores de esta ficha son orientativos para presupuesto.", "datosTecnicos": [{"label": "Resistencia del hormigón", "value": "H-21 (21 MPa)"}, {"label": "Recubrimiento mínimo", "value": "5 cm (contacto con suelo)"}, {"label": "Cuantía orientativa de acero", "value": "40–70 kg/m³"}], "notas": ["Separadores para respetar el recubrimiento.", "Vibrar o varillar; curado húmedo al menos 7 días."], "fuente": "Valores de referencia de práctica habitual en AMBA. Ajustar al proyecto, al proveedor y al estudio de suelos o cálculo cuando corresponda."}$sheet$::jsonb),
