6\" stroke=\"#c08a70\" stroke-width=\"0.6\" /><rect x=\"414\" y=\"150\" width=\"92\" height=\"50\" fill=\"#d8a58a\" stroke=\"#9b6e57\" stroke-width=\"1\" /><rect x=\"422\" y=\"158\" width=\"20\" height=\"34\" fill=\"#f4e2d6\" stroke=\"#c08a70\" stroke-width=\"0.6\" /><rect x=\"450\" y=\"158\" width=\"20\" height=\"34\" fill=\"#f4e2d6\" stroke=\"#c08a70\" stroke-width=\"0.6\" /><rect x=\"478\" y=\"158\" width=\"20\" height=\"34\" fill=\"#f4e2d6\" stroke=\"#c08a70\" stroke-width=\"0.6\" /><path d=\"M34 200 L60 200 L56 186 L50 186 L50 150 L44 150 L44 186 L38 186 Z\" fill=\"#b9bec3\" stroke=\"#6f767c\"/><circle cx=\"47\" cy=\"194\" r=\"2\" fill=\"#3d454d\"/><path d=\"M154 200 L180 200 L176 186 L170 186 L170 150 L164 150 L164 186 L158 186 Z\" fill=\"#b9bec3\" stroke=\"#6f767c\"/><circle cx=\"167\" cy=\"194\" r=\"2\" fill=\"#3d454d\"/><path d=\"M274 200 L300 200 L296 186 L290 186 L290 150 L284 150 L284 186 L278 186 Z\" fill=\"#b9bec3\" stroke=\"#6f767c\"/><circle cx=\"287\" cy=\"194\" r=\"2\" fill=\"#3d454d\"/><path d=\"M394 200 L420 200 L416 186 L410 186 L410 150 L404 150 L404 186 L398 186 Z\" fill=\"#b9bec3\" stroke=\"#6f767c\"/><circle cx=\"407\" cy=\"194\" r=\"2\" fill=\"#3d454d\"/><path d=\"M514 200 L540 200 L536 186 L530 186 L530 150 L524 150 L524 186 L518 186 Z\" fill=\"#b9bec3\" stroke=\"#6f767c\"/><circle cx=\"527\" cy=\"194\" r=\"2\" fill=\"#3d454d\"/><rect x=\"30\" y=\"125\" width=\"500\" height=\"25\" fill=\"url(#p-horm)\" stroke=\"#6f767c\" stroke-width=\"1\" /><path d=\"M30 136 H530\" stroke=\"#7b8794\" stroke-width=\"1.4\" stroke-dasharray=\"8 4\"/><g stroke=\"#666\" stroke-width=\"1\"><line x1=\"47\" y1=\"230\" x2=\"167\" y2=\"230\"/><line x1=\"47\" y1=\"224\" x2=\"47\" y2=\"236\"/><line x1=\"167\" y1=\"224\" x2=\"167\" y2=\"236\"/></g><text class=\"dim\" x=\"107.0\" y=\"244\" text-anchor=\"middle\">≈ 0,50 m</text><g stroke=\"#666\" stroke-width=\"1\"><line x1=\"540\" y1=\"125\" x2=\"540\" y2=\"200\"/><line x1=\"534\" y1=\"125\" x2=\"546\" y2=\"125\"/><line x1=\"534\" y1=\"200\" x2=\"546\" y2=\"200\"/></g><text class=\"dim\" x=\"548\" y=\"166.5\" text-anchor=\"start\">17 cm</text><path d=\"M300 130 L300 70\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"300\" y=\"64\" text-anchor=\"middle\">Capa de compresión 5 cm + malla</text><path d=\"M410 175 L460 100\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"460\" y=\"94\" text-anchor=\"middle\">Bloque cerámico</text><path d=\"M167 195 L150 280\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"150\" y=\"292\" text-anchor=\"middle\">Vigueta pretensada</text></svg>", "pie": "Corte. Esquema ilustrativo, sin escala.", "descripcion": "Losa alivianada con viguetas pretensadas, bloques cerámicos entre viguetas y capa de compresión de hormigón con malla. Es la solución más usada en vivienda por su rapidez y bajo encofrado. El tipo de vigueta sale de la tabla del fabricante según luz y sobrecarga.", "datosTecnicos": [{"label": "Espesor total habitual", "value": "12 + 5 = 17 cm"}, {"label": "Separación de viguetas", "value": "≈ 0,50 m"}, {"label": "Luz máxima", "value": "según fabricante (≈ 5–6 m sin apuntalar intermedio)"}], "notas": ["Apuntalar según tabla del fabricante (en general cada 1,50 m).", "Mojar los bloques antes de hormigonar."], "fuente": "Valores de referencia de práctica habitual en AMBA. Ajustar al proyecto, al proveedor y al estudio de suelos o cálculo cuando corresponda."}$sheet$::jsonb),
