  ('PIS-CAR', $sheet${"version": 1, "ficha": "PIS-CAR", "gremio": "Contrapisos y carpetas", "titulo": "Carpeta de nivelación de cemento", "esquemaSvg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 590 300\" role=\"img\" aria-label=\"Carpeta de nivelación\"><defs><pattern id=\"p-mort\" width=\"10\" height=\"10\" patternUnits=\"userSpaceOnUse\"><rect width=\"10\" height=\"10\" fill=\"#e6e1d6\"/><circle cx=\"2\" cy=\"3\" r=\".6\" fill=\"#a9a293\"/><circle cx=\"7\" cy=\"7\" r=\".6\" fill=\"#a9a293\"/></pattern><pattern id=\"p-casc\" width=\"18\" height=\"14\" patternUnits=\"userSpaceOnUse\"><rect width=\"18\" height=\"14\" fill=\"#ddd5c6\"/><path d=\"M2 3l5 1-2 4zM11 8l5-1 1 4-4 1z\" fill=\"#c98f74\"/></pattern></defs><style>.lbl{font:11px Arial,Helvetica,sans-serif;fill:#333}.dim{font:10.5px Arial,Helvetica,sans-serif;fill:#555}</style><rect x=\"30\" y=\"170\" width=\"500\" height=\"80\" fill=\"url(#p-casc)\" stroke=\"#8d7e66\" stroke-width=\"1\" /><rect x=\"30\" y=\"150\" width=\"500\" height=\"20\" fill=\"url(#p-mort)\" stroke=\"#8f887a\" stroke-width=\"1\" /><path d=\"M40 140 H520\" stroke=\"#2563eb\" stroke-dasharray=\"3 3\"/><path d=\"M500 132 l8 8 l-8 8 M60 132 l-8 8 l8 8\" fill=\"none\" stroke=\"#2563eb\"/><g stroke=\"#666\" stroke-width=\"1\"><line x1=\"540\" y1=\"150\" x2=\"540\" y2=\"170\"/><line x1=\"534\" y1=\"150\" x2=\"546\" y2=\"150\"/><line x1=\"534\" y1=\"170\" x2=\"546\" y2=\"170\"/></g><text class=\"dim\" x=\"548\" y=\"164.0\" text-anchor=\"start\">2 cm</text><path d=\"M250 160 L250 90\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"250\" y=\"84\" text-anchor=\"middle\">Carpeta de cemento 1 : 3 (fratasada)</text><text class=\"lbl\" x=\"280\" y=\"128\" text-anchor=\"middle\">Nivel / pendiente de proyecto</text><path d=\"M150 210 L150 280\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"150\" y=\"292\" text-anchor=\"middle\">Contrapiso existente</text></svg>", "pie": "Corte. Esquema i