 height=\"12\" fill=\"#6b7280\" stroke=\"none\" stroke-width=\"0\" /><rect x=\"476\" y=\"152\" width=\"4\" height=\"12\" fill=\"#6b7280\" stroke=\"none\" stroke-width=\"0\" /><g stroke=\"#666\" stroke-width=\"1\"><line x1=\"142\" y1=\"136\" x2=\"252\" y2=\"136\"/><line x1=\"142\" y1=\"130\" x2=\"142\" y2=\"142\"/><line x1=\"252\" y1=\"130\" x2=\"252\" y2=\"142\"/></g><text class=\"dim\" x=\"197.0\" y=\"130\" text-anchor=\"middle\">pieza 30–60 cm</text><path d=\"M250 168 L330 110\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"332\" y=\"106\" text-anchor=\"start\">Adhesivo cementicio (llana dentada)</text><path d=\"M142 158 L100 100\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"40\" y=\"96\" text-anchor=\"start\">Junta 2–3 mm con pastina</text><path d=\"M420 180 L440 230\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"442\" y=\"240\" text-anchor=\"start\">Carpeta</text><path d=\"M200 220 L200 280\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"200\" y=\"292\" text-anchor=\"middle\">Contrapiso</text></svg>", "pie": "Corte. Esquema ilustrativo, sin escala.", "descripcion": "Colocación de piezas cerámicas o de porcellanato con adhesivo cementicio sobre carpeta, con junta tomada con pastina. Para porcellanato usar adhesivo específico y doble encolado en piezas grandes.", "datosTecnicos": [{"label": "Junta", "value": "2–3 mm"}, {"label": "Desperdicio", "value": "5–10 % (más en diagonal)"}, {"label": "Adhesivo", "value": "llana dentada 8–10 mm"}], "notas": ["Replantear desde el centro o desde la puerta de acceso.", "No pisar ni tomar juntas antes de 24 h."], "fuente": "Valores de referencia de práctica habitual en AMBA. Ajustar al proyecto, al proveedor y al estudio de suelos o cálculo cuando corresponda."}$sheet$::jsonb),
  ('REV-CER', $sheet${"version": 1, "ficha": "REV-CER", "gremio": "Pisos y revestimientos", "titulo": "Revestimiento cerámico en muros", "esquemaSvg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 590 300\" role=\"img\" aria-label=\"Revestimiento cerámico en muro\"><defs><pattern id=\"p-mamp\" width=\"24\" height=\"14\" patternUnits=\"userSpaceOnUse\"><rect width=\"24\" height=\"14\" fill=\"#d8a58a\"/><path d=\"M0 0H24M0 7H24M12 0V7M0 7V14M24 7V14\" stroke=\"#f1e6dc\" stroke-width=\"1.4\"/></pattern><pattern id=\"p-mort\" width=\"10\" height=\"10\" patternUnits=\"userSpaceOnUse\"><rect width=\"10\" height=\"10\" fill=\"#e6e1d6\"/><circle cx=\"2\" cy=\"3\" r=\".6\" fill=\"#a9a293\"/><circle cx=\"7\" cy=\"7\" r=\".6\" fill=\"#a9a293\"/></pattern></defs><style>.lbl{font:11px Arial,Helvetica,sans-serif;fill:#333}.dim{font:10.5px Arial,Helvetica,sans-serif;fill:#555}</style><rect x=\"60\" y=\"40\" width=\"120\" height=\"220\" fill=\"url(#p-mamp)\" stroke=\"#9b6e57\" stroke-width=\"1\" /><rect x=\"180\" y=\"40\" width=\"22\" height=\"220\" fill=\"url(#p-mort)\" stroke=\"#a59e8e\" stroke-width=\"1\" /><rect x=\"202\" y=\"40\" width=\"6\" height=\"220\" fill=\"#cfd3d6\" stroke=\"#9aa0a6\" stroke-width=\"1\" /><rect x=\"208\" y=\"42\" width=\"10\" height=\"70\" fill=\"#eef2f5\" stroke=\"#8d8f93\" stroke-width=\"1\" /><rect x=\"208\" y=\"116\" width=\"10\" height=\"70\" fill=\"#eef2f5\" stroke=\"#8d8f93\" stroke-width=\"1\" /><rect x=\"208\" y=\"190\" width=\"10\" height=\"70\" fill=\"#eef2f5\" stroke=\"#8d8f93\" stroke-width=\"1\" /><path d=\"M120 70 L330 70\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"336\" y=\"74\" text-anchor=\"start\">Muro</text><path d=\"M191 120 L330 120\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"336\" y=\"124\" text-anchor=\"start\">Revoque grueso fratasado (sin fino)</text><path d=\"M205 170 L330 170\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=