  ('PIS-ZOC', $sheet${"version": 1, "ficha": "PIS-ZOC", "gremio": "Pisos y revestimientos", "titulo": "Zócalo cerámico o de porcellanato", "esquemaSvg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 590 300\" role=\"img\" aria-label=\"Zócalo cerámico\"><defs><pattern id=\"p-mamp\" width=\"24\" height=\"14\" patternUnits=\"userSpaceOnUse\"><rect width=\"24\" height=\"14\" fill=\"#d8a58a\"/><path d=\"M0 0H24M0 7H24M12 0V7M0 7V14M24 7V14\" stroke=\"#f1e6dc\" stroke-width=\"1.4\"/></pattern><pattern id=\"p-mort\" width=\"10\" height=\"10\" patternUnits=\"userSpaceOnUse\"><rect width=\"10\" height=\"10\" fill=\"#e6e1d6\"/><circle cx=\"2\" cy=\"3\" r=\".6\" fill=\"#a9a293\"/><circle cx=\"7\" cy=\"7\" r=\".6\" fill=\"#a9a293\"/></pattern><pattern id=\"p-casc\" width=\"18\" height=\"14\" patternUnits=\"userSpaceOnUse\"><rect width=\"18\" height=\"14\" fill=\"#ddd5c6\"/><path d=\"M2 3l5 1-2 4zM11 8l5-1 1 4-4 1z\" fill=\"#c98f74\"/></pattern></defs><style>.lbl{font:11px Arial,Helvetica,sans-serif;fill:#333}.dim{font:10.5px Arial,Helvetica,sans-serif;fill:#555}</style><rect x=\"380\" y=\"30\" width=\"120\" height=\"230\" fill=\"url(#p-mamp)\" stroke=\"#9b6e57\" stroke-width=\"1\" /><rect x=\"362\" y=\"30\" width=\"18\" height=\"230\" fill=\"url(#p-mort)\" stroke=\"#a59e8e\" stroke-width=\"1\" /><rect x=\"40\" y=\"230\" width=\"340\" height=\"30\" fill=\"url(#p-casc)\" stroke=\"#8d7e66\" stroke-width=\"1\" /><rect x=\"40\" y=\"218\" width=\"340\" height=\"12\" fill=\"url(#p-mort)\" stroke=\"#8f887a\" stroke-width=\"1\" /><rect x=\"40\" y=\"210\" width=\"322\" height=\"8\" fill=\"#e9e2d0\" stroke=\"#8d8676\" stroke-width=\"1\" /><rect x=\"356\" y=\"160\" width=\"6\" height=\"58\" fill=\"#cfd3d6\" stroke=\"#9aa0a6\" stroke-width=\"1\" /><rect x=\"348\" y=\"160\" width=\"8\" height=\"50\" fill=\"#e9e2d0\" stroke=\"#8d8676\" stroke-width=\"1\" /><g stroke=\"#666\" stroke-width=\"1\"><line x1=\"330\" y1=\"160\" x2=\"330\" y2=\"210\"/><line x1=\"324\" y1=\"160\" x2=\"336\" y2=\"160\"/><line x1=\"324\" y1=\"210\" x2=\"336\" y2=\"210\"/></g><text class=\"dim\" x=\"322\" y=\"189.0\" text-anchor=\"end\">7–10 cm</text><path d=\"M352 170 L250 90\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"250\" y=\"84\" text-anchor=\"middle\">Zócalo cerámico / porcellanato</text><path d=\"M359 190 L470 290\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"530\" y=\"292\" text-anchor=\"end\">Adhesivo + pastina</text><path d=\"M150 214 L150 140\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"150\" y=\"134\" text-anchor=\"middle\">Piso</text><text class=\"lbl\" x=\"440\" y=\"22\" text-anchor=\"middle\">Muro revocado</text></svg>", "pie": "Corte. Esquema ilustrativo, sin escala.", "descripcion": "Colocación de zócalo cerámico o de porcellanato cortado del mismo piso, pegado con adhesivo sobre el revoque, con junta tomada con pastina.", "datosTecnicos": [{"label": "Altura", "value": "7–10 cm"}, {"label": "Desperdicio", "value": "≈ 5 %"}, {"label": "Junta con el piso", "value": "2–3 mm"}], "notas": ["Colocar después del piso, alineado con sus juntas.", "Inglete o pieza esquinera en los ángulos."], "fuente": "Valores de referencia de práctica habitual en AMBA. Ajustar al proyecto, al proveedor y al estudio de suelos o cálculo cuando corresponda."}$sheet$::jsonb),
  ('CS-TAB-70-1x12', $sheet${"version": 1, "ficha": "CS-TAB-70-1x12", "gremio": "Construcción en seco", "titulo": "Tabique de placa de yeso — estructura 70, simple placa 12,5 mm por cara", "esquemaSvg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 560 300\" role=\"img\" aria-label=\"Corte horizontal de tabique de placa de yeso\"><style>.lbl{font:11px Arial,Helvetica,sans-serif;fill:#333}.dim{font:10.5px Arial,Helvetica,sans-serif;fill:#555}</style>\n        <defs>\n          <pattern id=\"lana1\" width=\"14\" height=\"14\" patternUnits=\"userSpaceOnUse\">\n            <path d=\"M0 7 Q3.5 0 7 7 T14 7\" fill=\"none\" stroke=\"#d1a85e\" stroke-width=\"1\"/>\n          </pattern>\n        </defs>\n        <!-- placas -->\n        <rect x=\"40\" y=\"110\" width=\"440\" height=\"12.5\" fill=\"#f3efe6\" stroke=\"#8a8170\"/>\n        <rect x=\"40\" y=\"192.5\" width=\"440\" height=\"12.5\" fill=\"#f3efe6\" stroke=\"#8a8170\"/>\n        <!-- lana -->\n        <rect x=\"40\" y=\"122.5\" width=\"440\" height=\"70\" fill=\"url(#lana1)\" opacity=\".9\"/>\n        <!-- montantes (C 69x35) cada 160 px = 0,40 m -->\n        <g fill=\"none\" stroke=\"#7b8794\" stroke-width=\"2.4\">\n          <path d=\"M95 123.5 h-14 v68 h14\"/>\n          <path d=\"M255 123.5 h-14 v68 h14\"/>\n          <path d=\"M415 123.5 h-14 v68 h14\"/>\n        </g>\n        <!-- tornillos -->\n        <g stroke=\"#333\" stroke-width=\"1.6\">\n          <line x1=\"88\" y1=\"104\" x2=\"88\" y2=\"130\"/><line x1=\"248\" y1=\"104\" x2=\"248\" y2=\"130\"/><line x1=\"408\" y1=\"104\" x2=\"408\" y2=\"130\"/>\n          <line x1=\"88\" y1=\"185\" x2=\"88\" y2=\"211\"/><line x1=\"248\" y1=\"185\" x2=\"248\" y2=\"211\"/><line x1=\"408\" y1=\"185\" x2=\"408\" y2=\"211\"/>\n        </g>\n        <!-- junta de placas con cinta -->\n        <rect x=\"236\" y=\"106\" width=\"24\" height=\"4\" fill=\"#9db8d6\"/>\n        <!-- cotas -->\n        <g stroke=\"#666\" stroke-width=\"1\">\n          <line x1=\"88\" y1=\"70\" x2=\"248\" y2=\"70\"/><line x1=\"248\" y1=\"70\" x2=\"408\" y2=\"70\"/>\n          <line x1=\"88\" y1=\"64\" x2=\"88\" y2=\"76\"/><line x1=\"248\" y1=\"64\" x2=\"248\" y2=\"76\"/><line x1=\"408\" y1=\"64\" x2=\"408\" y2=\"76\"/>\n          <line x1=\"495\" y1=\"110\" x2=\"495\" y2=\"205\"/><line x1=\"489\" y1=\"110\" x2=\"501\" y2=\"110\"/><line x1=\"489\" y1=\"205\" x2=\"501\" y2=\"205\"/>\n        </g>\n        <text class=\"dim\" x=\"168\" y=\"62\" text-anchor=\"middle\">0,40 m</text>\n        <text class=\"dim\" x=\"328\" y=\"62\" text-anchor=\"middle\">0,40 m</text>\n        <text class=\"dim\" x=\"505\" y=\"161\">95 mm</text>\n        <!-- rótulos -->\n        <g stroke=\"#999\" stroke-width=\".8\" fill=\"none\">\n          <path d=\"M150 116 L150 40\"/><path d=\"M175 160 L175 255\"/><path d=\"M255 150 L300 255\"/><path d=\"M408 211 L430 255\"/><path d=\"M248 106 L230 40\"/>\n        </g>\n        <text class=\"lbl\" x=\"150\" y=\"34\" text-anchor=\"middle\">Placa de yeso 12,5 mm</text>\n        <text class=\"lbl\" x=\"235\" y=\"34\" text-anchor=\"start\">Cinta + masilla en junta</text>\n        <text class=\"lbl\" x=\"175\" y=\"270\" text-anchor=\"middle\">Lana de vidrio 50–70 mm</text>\n        <text class=\"lbl\" x=\"300\" y=\"270\" text-anchor=\"middle\">Montante 69 mm</text>\n        <text class=\"lbl\" x=\"440\" y=\"270\" text-anchor=\"middle\">Tornillo T2</text>\n      </svg>", "pie": "Corte horizontal. Esquema ilustrativo, sin escala.", "descripcion": "Tabique interior no portante de perfiles de acero galvanizado (solera 70 y montante 69 cada 0,40 m) con una placa de yeso de 12,5 mm atornillada en cada cara y aislación de lana en el interior. Para divisiones en ambientes secos; en baños y cocinas va con placa resistente a la humedad.", "datosTecnicos": [{"label": "Espesor final", "value": "95 mm"}, {"label": "Peso aproximado", "value": "22 kg/m²"}, {"label": "Altura máxima (montantes c/0,40 / c/0,48)", "value": "4,00 / 3,75 m"}, {"label": "Aislación acústica Rw (sin / con lana 70 mm)", "value": "37 / 45 dB"}, {"label": "Resistencia al fuego", "value": "F30"}], "notas": ["Placa separada 15 mm del piso; juntas trabadas entre caras.", "Prever refuerzos para alacenas, mesadas y marcos antes de emplacar."], "fuente": "Valores de referencia según Manual Técnico Durlock (tomos 2, 3 y 4). Verificar con el fabricante del sistema utilizado."}$sheet$::jsonb),
  ('CS-CIE-JT-12', $sheet${"version": 1, "ficha": "CS-CIE-JT-12", "gremio": "Construcción en seco", "titulo": "Cielorraso suspendido de placa de yeso junta tomada — estructura 35", "esquemaSvg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 560 300\" role=\"img\" aria-label=\"Corte vertical de cielorraso suspendido\"><style>.lbl{font:11px Arial,Helvetica,sans-serif;fill:#333}.dim{font:10.5px Arial,Helvetica,sans-serif;fill:#555}</style>\n        <defs>\n          <pattern id=\"horm\" width=\"10\" height=\"10\" patternUnits=\"userSpaceOnUse\">\n            <rect width=\"10\" height=\"10\" fill=\"#bfc3c7\"/><circle cx=\"3\" cy=\"3\" r=\"1\" fill=\"#9aa0a6\"/><circle cx=\"8\" cy=\"7\" r=\".8\" fill=\"#9aa0a6\"/>\n          </pattern>\n          <pattern id=\"mamp\" width=\"20\" height=\"12\" patternUnits=\"userSpaceOnUse\">\n            <rect width=\"20\" height=\"12\" fill=\"#c9c4bb\"/><path d=\"M0 0H20M0 6H20M10 0V6M0 6V12M20 6V12\" stroke=\"#aaa39a\" stroke-width=\".8\"/>\n          </pattern>\n        </defs>\n        <!-- losa -->\n        <rect x=\"30\" y=\"30\" width=\"470\" height=\"36\" fill=\"url(#horm)\" stroke=\"#8d9297\"/>\n        <!-- muro -->\n        <rect x=\"30\" y=\"66\" width=\"34\" height=\"200\" fill=\"url(#mamp)\" stroke=\"#9b958c\"/>\n        <!-- velas rígidas -->\n        <g stroke=\"#7b8794\" stroke-width=\"3\">\n          <line x1=\"200\" y1=\"66\" x2=\"200\" y2=\"196\"/>\n          <line x1=\"400\" y1=\"66\" x2=\"400\" y2=\"196\"/>\n        </g>\n        <!-- anclajes -->\n        <g fill=\"#333\"><rect x=\"195\" y=\"66\" width=\"10\" height=\"5\"/><rect x=\"395\" y=\"66\" width=\"10\" height=\"5\"/></g>\n        <!-- solera perimetral -->\n        <path d=\"M64 196 h12 M64 212 h12 M64 196 v16\" stroke=\"#7b8794\" stroke-width=\"2.4\" fill=\"none\"/>\n        <!-- montantes en corte (cada 0,40) -->\n        <g fill=\"#7b8794\">\n          <rect x=\"110\" y=\"200\" width=\"10\" height=\"12\"/><rect x=\"190\" y=\"200\" width=\"10\