. Superficie continua, lista para pintar.", "datosTecnicos": [{"label": "Peso aproximado", "value": "11,5 kg/m²"}, {"label": "Separación de montantes / vigas maestras", "value": "0,40 / 1,20 m"}, {"label": "Velas rígidas", "value": "c/1,00 m máx."}, {"label": "Juntas de trabajo", "value": "c/10 m máx."}], "notas": ["Nivelar con láser antes de fijar la solera perimetral.", "Prever tapas de inspección y refuerzos para artefactos de iluminación."], "fuente": "Valores de referencia según Manual Técnico Durlock (tomos 2, 3 y 4). Verificar con el fabricante del sistema utilizado."}$sheet$::jsonb),
  ('CS-REV-OM-12', $sheet${"version": 1, "ficha": "CS-REV-OM-12", "gremio": "Construcción en seco", "titulo": "Revestimiento de placa de yeso sobre perfiles Omega", "esquemaSvg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 560 300\" role=\"img\" aria-label=\"Corte horizontal de revestimiento sobre perfil omega\"><style>.lbl{font:11px Arial,Helvetica,sans-serif;fill:#333}.dim{font:10.5px Arial,Helvetica,sans-serif;fill:#555}</style>\n        <defs>\n          <pattern id=\"mamp2\" width=\"20\" height=\"12\" patternUnits=\"userSpaceOnUse\">\n            <rect width=\"20\" height=\"12\" fill=\"#c9c4bb\"/><path d=\"M0 0H20M0 6H20M10 0V6M0 6V12M20 6V12\" stroke=\"#aaa39a\" stroke-width=\".8\"/>\n          </pattern>\n        </defs>\n        <!-- muro existente -->\n        <rect x=\"40\" y=\"70\" width=\"440\" height=\"70\" fill=\"url(#mamp2)\" stroke=\"#9b958c\"/>\n        <!-- omegas -->\n        <g fill=\"none\" stroke=\"#7b8794\" stroke-width=\"2.4\">\n          <path d=\"M70 140 h12 v13 h20 v-13 h12\"/>\n          <path d=\"M230 140 h12 v13 h20 v-13 h12\"/>\n          <path d=\"M390 140 h12 v13 h20 v-13 h12\"/>\n        </g>\n        <!-- tarugos -->\n        <g stroke=\"#333\" stroke-width=\"2\">\n          <line x1=\"76\" y1=\"141\" x2=\"76\" y2=\"112\"/><line x1=\"236\" y1=\"141\" x2=\"236\" y2=\"112\"/><line x1=\"396\" y1=\"141\" x2=\"396\" y2=\"112\"/>\n        </g>\n        <!-- placa -->\n        <rect x=\"40\" y=\"153\" width=\"440\" height=\"12.5\" fill=\"#f3efe6\" stroke=\"#8a8170\"/>\n        <!-- tornillos T2 -->\n        <g stroke=\"#333\" stroke-width=\"1.6\">\n          <line x1=\"92\" y1=\"149\" x2=\"92\" y2=\"172\"/><line x1=\"252\" y1=\"149\" x2=\"252\" y2=\"172\"/><line x1=\"412\" y1=\"149\" x2=\"412\" y2=\"172\"/>\n        </g>\n        <!-- cotas -->\n        <g stroke=\"#666\" stroke-width=\"1\">\n          <line x1=\"92\" y1=\"205\" x2=\"252\" y2=\"205\"/><line x1=\"252\" y1=\"205\" x2=\"412\" y2=\"205\"/>\n          <line x1=\"9