  ('SAN-CLO', $sheet${"version": 1, "ficha": "SAN-CLO", "gremio": "Instalación sanitaria", "titulo": "Cañería cloacal de PVC 110 enterrada", "esquemaSvg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 590 300\" role=\"img\" aria-label=\"Cañería cloacal PVC 110\"><defs><pattern id=\"p-tierra\" width=\"16\" height=\"16\" patternUnits=\"userSpaceOnUse\"><rect width=\"16\" height=\"16\" fill=\"#e2d5bf\"/><path d=\"M2 4l4 4M10 2l3 3M6 12l4 3\" stroke=\"#b9a684\" stroke-width=\"1\"/></pattern><pattern id=\"p-arena\" width=\"8\" height=\"8\" patternUnits=\"userSpaceOnUse\"><rect width=\"8\" height=\"8\" fill=\"#efe3c4\"/><circle cx=\"2\" cy=\"2\" r=\".7\" fill=\"#c7b17b\"/><circle cx=\"6\" cy=\"5\" r=\".7\" fill=\"#c7b17b\"/></pattern></defs><style>.lbl{font:11px Arial,Helvetica,sans-serif;fill:#333}.dim{font:10.5px Arial,Helvetica,sans-serif;fill:#555}</style><defs><marker id=\"arr2\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0 0L6 3L0 6z\" fill=\"#444\"/></marker></defs><rect x=\"30\" y=\"80\" width=\"500\" height=\"200\" fill=\"url(#p-tierra)\" stroke=\"none\" stroke-width=\"0\" /><path d=\"M30 80 H530\" stroke=\"#6b5a3c\" stroke-width=\"2\"/><path d=\"M60 120 L440 160 L440 200 L60 160 Z\" fill=\"url(#p-arena)\" stroke=\"#b39b62\"/><path d=\"M60 140 L440 180\" stroke=\"#e07a2f\" stroke-width=\"10\" stroke-linecap=\"round\"/><rect x=\"440\" y=\"80\" width=\"70\" height=\"130\" fill=\"#c4c8cc\" stroke=\"#6f767c\" stroke-width=\"1\" /><rect x=\"452\" y=\"92\" width=\"46\" height=\"106\" fill=\"#f2f3f4\" stroke=\"#9aa0a6\" stroke-width=\"1\" /><path d=\"M250 160 L250 40\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"250\" y=\"34\" text-anchor=\"middle\">Caño PVC 110 mm (junta elástica)</text><path d=\"M150 158 L150 250\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"150\" y=\"262\" text-anchor=\"middle\">Lecho y recubrimiento de arena</text><path d=\"M475 140 L475 40\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"475\" y=\"34\" text-anchor=\"middle\">Cámara de inspección</text><path d=\"M120 220 L330 242\" stroke=\"#444\" marker-end=\"url(#arr2)\"/><text class=\"lbl\" x=\"320\" y=\"280\" text-anchor=\"middle\">pendiente 1:20 a 1:60</text></svg>", "pie": "Corte longitudinal. Esquema ilustrativo, sin escala.", "descripcion": "Tendido de cañería cloacal principal de PVC de 110 mm con junta elástica, en zanja con lecho y recubrimiento de arena, hasta cámara de inspección. Incluye la zanja liviana; las cámaras se presupuestan aparte.", "datosTecnicos": [{"label": "Pendiente", "value": "1:20 a 1:60"}, {"label": "Tapada mínima", "value": "≈ 0,30 m"}, {"label": "Material", "value": "PVC 3,2 mm con junta elástica"}], "notas": ["Prueba hidráulica antes de tapar.", "Cámaras en cambios de dirección y cada 30 m como máximo."], "fuente": "Valores de referencia de práctica habitual en AMBA. Ajustar al proyecto, al proveedor y al estudio de suelos o cálculo cuando corresponda."}$sheet$::jsonb),
  ('SAN-AGU', $sheet${"version": 1, "ficha": "SAN-AGU", "gremio": "Instalación sanitaria", "titulo": "Boca de agua fría y caliente en termofusión", "esquemaSvg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 590 300\" role=\"img\" aria-label=\"Boca de agua fría y caliente\"><style>.lbl{font:11px Arial,Helvetica,sans-serif;fill:#333}.dim{font:10.5px Arial,Helvetica,sans-serif;fill:#555}</style><rect x=\"40\" y=\"40\" width=\"480\" height=\"220\" fill=\"#f3ece4\" stroke=\"#c9b8a6\" stroke-width=\"1\" /><path d=\"M40 210 H300 V120\" fill=\"none\" stroke=\"#2563eb\" stroke-width=\"5\"/><path d=\"M40 230 H340 V120\" fill=\"none\" stroke=\"#dc2626\" stroke-width=\"5\"/><circle cx=\"300\" cy=\"112\" r=\"9\" fill=\"#fff\" stroke=\"#2563eb\" stroke-width=\"3\"/><circle cx=\"340\" cy=\"112\" r=\"9\" fill=\"#fff\" stroke=\"#dc2626\" stroke-width=\"3\"/><path d=\"M290 104 h60\" stroke=\"#666\" stroke-width=\"2\"/><rect x=\"110\" y=\"202\" width=\"16\" height=\"16\" fill=\"#fff\" stroke=\"#2563eb\" stroke-width=\"2\" /><g stroke=\"#666\" stroke-width=\"1\"><line x1=\"380\" y1=\"120\" x2=\"380\" y2=\"260\"/><line x1=\"374\" y1=\"120\" x2=\"386\" y2=\"120\"/><line x1=\"374\" y1=\"260\" x2=\"386\" y2=\"260\"/></g><text class=\"dim\" x=\"388\" y=\"194.0\" text-anchor=\"start\">h según artefacto</text><path d=\"M300 105 L260 60\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"260\" y=\"54\" text-anchor=\"middle\">Codo / conexión a grifería</text><path d=\"M118 210 L118 120\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"118\" y=\"114\" text-anchor=\"middle\">Llave de paso</text><text class=\"lbl\" x=\"60\" y=\"200\" text-anchor=\"start\">Agua fría</text><text class=\"lbl\" x=\"60\" y=\"252\" text-anchor=\"start\">Agua caliente</text><text class=\"lbl\" x=\"470\" y=\"240\" text-anchor=\"middle\">Termofusión PPR</text><text class=\"lbl\" x=\"470\" y=\"254\" text-anchor=\"middle\">20–25 mm embutido</text></svg>", "pie": "Elevación. Esquema ilustrativo, sin escala.", "descripcion": "Alimentación de un artefacto (lavatorio, pileta, ducha) con agua fría y caliente en polipropileno por termofusión, embutida en muro, desde el ramal hasta la conexión de la grifería.", "datosTecnicos": [{"label": "Material", "value": "PPR termofusión 20–25 mm"}, {"label": "Presión de prueba", "value": "≈ 1,5 veces la de servicio"}, {"label": "Alturas", "value": "según artefacto y grifería"}], "notas": ["Aislar la cañería de agua caliente.", "Prueba de presión antes de revocar o revestir."], "fuente": "Valores de referencia de práctica habitual en AMBA. Ajustar al proyecto, al proveedor y al estudio de suelos o cálculo cuando corresponda."}$sheet$::jsonb),
