  ('PIN-LAT', $sheet${"version": 1, "ficha": "PIN-LAT", "gremio": "Pintura", "titulo": "Pintura látex interior sobre revoque", "esquemaSvg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 590 300\" role=\"img\" aria-label=\"Pintura látex interior\"><defs><pattern id=\"p-mamp\" width=\"24\" height=\"14\" patternUnits=\"userSpaceOnUse\"><rect width=\"24\" height=\"14\" fill=\"#d8a58a\"/><path d=\"M0 0H24M0 7H24M12 0V7M0 7V14M24 7V14\" stroke=\"#f1e6dc\" stroke-width=\"1.4\"/></pattern><pattern id=\"p-mort\" width=\"10\" height=\"10\" patternUnits=\"userSpaceOnUse\"><rect width=\"10\" height=\"10\" fill=\"#e6e1d6\"/><circle cx=\"2\" cy=\"3\" r=\".6\" fill=\"#a9a293\"/><circle cx=\"7\" cy=\"7\" r=\".6\" fill=\"#a9a293\"/></pattern></defs><style>.lbl{font:11px Arial,Helvetica,sans-serif;fill:#333}.dim{font:10.5px Arial,Helvetica,sans-serif;fill:#555}</style><rect x=\"60\" y=\"40\" width=\"120\" height=\"210\" fill=\"url(#p-mamp)\" stroke=\"#9b6e57\" stroke-width=\"1\" /><path d=\"M120.0 60 L330 60\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"336\" y=\"64\" text-anchor=\"start\">Muro</text><rect x=\"180\" y=\"40\" width=\"20\" height=\"210\" fill=\"url(#p-mort)\" stroke=\"#a59e8e\" stroke-width=\"1\" /><path d=\"M190.0 105 L330 105\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"336\" y=\"109\" text-anchor=\"start\">Revoque fino (sano y seco)</text><rect x=\"200\" y=\"40\" width=\"4\" height=\"210\" fill=\"#e5e7eb\" stroke=\"#9aa0a6\" stroke-width=\"1\" /><path d=\"M202.0 150 L330 150\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"336\" y=\"154\" text-anchor=\"start\">Fijador sellador</text><rect x=\"204\" y=\"40\" width=\"4\" height=\"210\" fill=\"#f8fafc\" stroke=\"#9aa0a6\" stroke-width=\"1\" /><path d=\"M206.0 195 L330 195\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"336\" y=\"199\" text-anchor=\"start\">Enduido (donde haga falta) y lija