  ('PIN-ESM', $sheet${"version": 1, "ficha": "PIN-ESM", "gremio": "Pintura", "titulo": "Esmalte sintético sobre carpintería metálica", "esquemaSvg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 590 300\" role=\"img\" aria-label=\"Esmalte sintético sobre metal\"><style>.lbl{font:11px Arial,Helvetica,sans-serif;fill:#333}.dim{font:10.5px Arial,Helvetica,sans-serif;fill:#555}</style><rect x=\"80\" y=\"120\" width=\"380\" height=\"22\" fill=\"#9aa3ab\" stroke=\"#4b5563\" stroke-width=\"1\" /><rect x=\"80\" y=\"112\" width=\"380\" height=\"8\" fill=\"#b91c1c\" stroke=\"#7f1d1d\" stroke-width=\"1\" /><rect x=\"80\" y=\"106\" width=\"380\" height=\"6\" fill=\"#1f2937\" stroke=\"#111\" stroke-width=\"1\" /><path d=\"M200 131 L200 230\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"200\" y=\"242\" text-anchor=\"middle\">Superficie metálica desengrasada y lijada</text><path d=\"M320 116 L380 60\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"380\" y=\"54\" text-anchor=\"middle\">Fondo antióxido</text><path d=\"M150 109 L120 60\" stroke=\"#999\" stroke-width=\".8\" fill=\"none\"/><text class=\"lbl\" x=\"120\" y=\"54\" text-anchor=\"middle\">2 manos de esmalte sintético</text><g stroke=\"#666\" stroke-width=\"1\"><line x1=\"80\" y1=\"180\" x2=\"460\" y2=\"180\"/><line x1=\"80\" y1=\"174\" x2=\"80\" y2=\"186\"/><line x1=\"460\" y1=\"174\" x2=\"460\" y2=\"186\"/></g><text class=\"dim\" x=\"270.0\" y=\"194\" text-anchor=\"middle\">carpintería / reja / baranda</text></svg>", "pie": "Corte de capas. Esquema ilustrativo.", "descripcion": "Pintura de carpinterías, rejas y barandas metálicas: desengrase, lijado, fondo antióxido y dos manos de esmalte sintético.", "datosTecnicos": [{"label": "Manos", "value": "antióxido + 2 de esmalte"}, {"label": "Rendimiento esmalte (por mano)", "value": "≈ 12–14 m²/l"}, {"label": "Medición", "value": "superficie desarrollada"}], "notas": ["Quitar todo el óxido suelto antes del fondo.", "En rejas, medir 2 caras × superficie aparente × coef. 0,7–1."], "fuente": "Valores de referencia de práctica habitual en AMBA. Ajustar al proyecto, al proveedor y al estudio de suelos o cálculo cuando corresponda."}$sheet$::jsonb),
